// _shared/config.ts - Fonte única de kill-switch + knobs + CORS
// Consumido pelos dois harnesses (darcy-chat texto + darcy-voice).
// darcy-chat/config.ts re-exporta tudo daqui para manter os imports antigos.

const ALLOWED_ORIGINS = [
    'https://aprender2.unb.br',
    'https://aprender3.unb.br',
    'https://aprender2teste.unb.br',
    'https://aprender3teste.unb.br',
    'http://localhost',
    'https://localhost',
];

export function getCorsHeaders(origin?: string): Record<string, string> {
    const allowed = origin && ALLOWED_ORIGINS.some(a => origin.startsWith(a));
    return {
        'Access-Control-Allow-Origin': allowed ? origin : ALLOWED_ORIGINS[0],
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
        'Vary': 'Origin',
    };
}

// DEPRECATED: Use getCorsHeaders() instead. Kept for backward compat only.
export const _deprecatedCorsHeaders = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};
/** @deprecated Use getCorsHeaders() instead */
export const corsHeaders = _deprecatedCorsHeaders;

// ═══════════════════════════════════════════════════════════════════════════
// KILL-SWITCH — Darcy de curso (tutor verde, com tools)
// ───────────────────────────────────────────────────────────────────────────
// FEATURE FLAG: o Darcy de curso será lançado depois. No piloto roda APENAS o
// suporte técnico (azul). Mantenha false até o lançamento. Os DOIS harnesses
// (texto + voz) respeitam esta flag — quando false, anulam courseId/type
// (suporte-only) antes de montar instructions/tools.
// Para reativar: ponha true aqui E COURSE_DARCY_ENABLED=true no widget (App.tsx).
export const COURSE_DARCY_ENABLED = false;

// ═══════════════════════════════════════════════════════════════════════════
// HARNESS LLM — fonte única de verdade (modelos + knobs)
// ───────────────────────────────────────────────────────────────────────────
// FILOSOFIA: 100% GRÁTIS. Usamos modelos :free FIXOS (não o auto-roteador) como
// primário/fallbacks, porque comportamento reproduzível é o que torna os EVALS
// válidos — você aprova um modelo no eval e é ELE que atende o aluno. O harness
// (normalizeAnswer + isAcceptableAnswer + cascata) absorve as diferenças entre
// os modelos da lista. `openrouter/free` (auto-roteador) fica só como rede de
// segurança final, para Darcy nunca parar de responder.
//
// Ordem = ordem de tentativa. RODE `node evals/run.mjs` para confirmar/reordenar
// o primário conforme o placar — o catálogo :free do OpenRouter muda com o tempo.
// Limite OpenRouter free: ~1000 req/dia por conta (com ≥US$10 em créditos) e 20 RPM.
//
// CRITÉRIO DE SELEÇÃO (verificado contra as specs do harness):
//  - Faz tool calling (curso usa tool_choice:'auto'; agentLoop dá JSON.parse nos args).
//  - É variante INSTRUCT, não "reasoning": modelos thinking (deepseek-v4-flash,
//    gpt-oss) vazam raciocínio no suporte E quebram no loop de tools (v4-flash
//    exige replay de reasoning_content, que não fazemos → 400). Por isso ficam de fora.
//  - Tem previsibilidade razoável de continuar free.
// Se um ID sair do ar/deixar de ser free, o harness simplesmente cai pro próximo
// (callLLMDirect trata não-ok como skip) — sem quebrar.
// ORDENADO POR VELOCIDADE/DISPONIBILIDADE — só modelos RÁPIDOS, sem reasoning.
// Otimização de latência (2026-05-26): REMOVIDO o openai/gpt-oss-120b (~37s,
// reasoning) que era o backstop lento — quando a cascata caía nele, o aluno
// esperava ~37s. Em troca, lista mais longa de modelos :free pequenos/MoE
// (poucos params ativos = resposta rápida). Cada 429 nos "badalados" pula rápido
// (continue), e agora SEMPRE cai em outro modelo rápido, nunca num lento.
// Validados como :free no catálogo OpenRouter em 2026-05-26. Todos INSTRUCT
// (não-reasoning) e com tool calling — revalide com `node evals/run.mjs`.
export const MODEL_IDS: string[] = [
    'nvidia/nemotron-3-nano-30b-a3b:free',      // #1 rápido (~1,5–4s medido) + saída LIMPA, MoE 3b ativo
    'nvidia/nemotron-nano-9b-v2:free',          // #2 9b denso, pequeno e rápido
    'qwen/qwen3-next-80b-a3b-instruct:free',    // #3 MoE 3b ativo, rápido (429 às vezes → pula rápido)
    'z-ai/glm-4.5-air:free',                    // #4 "air" = variante leve/rápida
    'meta-llama/llama-3.3-70b-instruct:free',   // #5 qualidade PT-BR (429-prone, bom fallback)
    'nvidia/nemotron-3-super-120b-a12b:free',   // #6 MoE 12b ativo, mais qualidade
    'meta-llama/llama-3.2-3b-instruct:free',    // #7 3b ULTRA-rápido — fallback de disponibilidade
    'openrouter/free',                          // #8 rede de segurança final (auto-roteador free)
];

// Knobs centralizados. Temperatura baixa = menos divergência entre modelos.
export const LLM = {
    TEMPERATURE: 0.2,            // suporte/curso: respostas vêm de FAQ fixa → baixa variância
    TEMPERATURE_CLASSIFIER: 0.1,
    MAX_TOKENS: 600,             // suporte = respostas curtas; teto baixo corta tempo de geração
    MAX_TOKENS_CLASSIFIER: 200,
    TIMEOUT_MS: 30000,
    CLASSIFIER_TIMEOUT_MS: 8000,
    CLASSIFIER_MODEL: 'meta-llama/llama-3.3-70b-instruct:free',
    REFERER: 'https://aprender2.unb.br',
    TITLE: 'Darcy - Assistente Virtual UnB',
} as const;
